diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..74394a0 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,38 @@ export interface Record {
   warns: readonly string[];
 }

+const extractConstraintCore = (entry: string): string => {
+  const lower = entry.toLowerCase();
+
+  // Operational burden: "ops", "operate", "operational", "run", "maintain", "stateful", "always-on"
+  if (/\b(ops|operate|operational|run|maintain|stateful|always-on|infrastructure|service)\b/.test(lower)) {
+    return "ops_burden";
+  }
+
+  return entry;
+};
+
+const deduplicateEntries = (entries: readonly string[]): string[] => {
+  const seen = new Set<string>();
+  const result: string[] = [];
+
+  for (const entry of entries) {
+    const core = extractConstraintCore(entry);
+    if (!seen.has(core)) {
+      seen.add(core);
+      result.push(entry);
+    }
+  }
+
+  return result;
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of deduplicateEntries(record.ruledOut)) lines.push(`- ruled out: ${entry}`);
+    for (const entry of deduplicateEntries(record.limits)) lines.push(`- limit: ${entry}`);
+    for (const entry of deduplicateEntries(record.warns)) lines.push(`- warn: ${entry}`);
   }
   return lines.join("\n");
 };
